{"command":"python3 << 'PY'
import json, os, re, time
from pathlib import Path

EVID = Path("/home/vgpnk/Projects/shokunin/kumitate-shokunin/.ufo/waves/round-59/build/SentinelBounds")
EVID.mkdir(parents=True, exist_ok=True)
LANE = Path("/home/vgpnk/Projects/shokunin/kumitate-shokunin")
FLEET = Path("/home/vgpnk/Projects/shokunin")
BOUND = (LANE / ".ufo/waves/round-59").resolve()
WAVE_START = 1792888155  # earliest relaunch start in launcher-progress
SEATS = {
    "ExecRepair59","ExecDoctrine59","ExecCiteLive","ExecMap","ExecCensus","ExecCapture",
    "ExecProxy","ExecSelftest","RevS125Quote","RevS127Quote","RevS136Quote","RevS121Gone",
    "RevGateCount","RevCapabilityRows","RevUsedBy","RevPins","CritBaseNotZero","CritDropOne",
    "CritTheme","CritQuarantine","MutGhost","MutFamily","MutPipeRow","MutChecksPin",
    "ScoutS125Live","ScoutS127Live","ScoutCollision","ScoutFrontier","ScribeGateTable",
    "ConnectorSiblings","SentinelBounds","RevengerV1",
}

def inside(p: str) -> bool:
    try:
        rp = Path(p).resolve()
    except Exception:
        return False
    try:
        rp.relative_to(BOUND)
        return True
    except ValueError:
        return False

# --- extract write-like paths from streams and err/md ---
path_re = re.compile(r"/home/vgpnk/[^\s\"'\\<>|;&]+|/tmp/[A-Za-z0-9._/-]+|/fast/scratch/[^\s\"'\\]+|/dev/shm/[^\s\"'\\]+|/home/vgpnk/Projects/shokuknow[^\s\"'\\]*")
write_tools = {"Write", "Edit"}
# bash write indicators
write_cmd_re = re.compile(
    r"(?:^|[;&|`(]|&&|\|\|)\s*(?:mkdir|mktemp|touch|cp|mv|rm|tee|install|ln|truncate|dd|git\s+add|git\s+commit|git\s+checkout|git\s+reset|git\s+clean|jj\b|python3?\s+-c|node\s+-e)",
    re.I,
)
redir_re = re.compile(r"(?:>>?|\d>>?)\s*([^\s;&|]+)")

records = []
streams = list((LANE/".ufo/waves/round-59/w1").glob("*.stream.jsonl"))
streams += list((LANE/".ufo/waves/round-59/w1-abort").glob("*.stream.jsonl"))

def add(seat, kind, path, detail):
    path = path.rstrip(").,;:`")
    if path.endswith("\\"):
        path = path[:-1]
    records.append((seat, kind, path, inside(path), detail[:240]))

for sp in streams:
    seat = sp.name.split(".stream")[0]
    if seat not in SEATS and not sp.parent.name == "w1-abort":
        continue
    seat_label = seat if sp.parent.name == "w1" else f"abort:{seat}"
    with sp.open() as f:
        for i, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception:
                continue
            # assistant tool calls
            for tc in obj.get("tool_calls") or []:
                fn = (tc.get("function") or {})
                name = fn.get("name") or ""
                args_raw = fn.get("arguments") or ""
                try:
                    args = json.loads(args_raw) if isinstance(args_raw, str) else args_raw
                except Exception:
                    args = {"_raw": args_raw}
                if name in write_tools:
                    p = args.get("path") or ""
                    if p:
                        add(seat_label, f"tool:{name}", p, f"line {i}")
                elif name == "Bash":
                    cmd = args.get("command") or ""
                    if not isinstance(cmd, str):
                        continue
                    # redirections
                    for m in redir_re.finditer(cmd):
                        target = m.group(1).strip("'\"")
                        if target.startswith("/"):
                            add(seat_label, "bash-redir", target, cmd[:180].replace("\n"," "))
                    # absolute paths in commands that look like writes
                    if any(tok in cmd for tok in (" >", ">>", "mkdir", "mktemp", "tee ", "cp ", "mv ", "install ", "touch ", "truncate ", "git add", "git commit", "jj ")):
                        for m in path_re.finditer(cmd):
                            add(seat_label, "bash-path-in-writeish", m.group(0), cmd[:180].replace("\n"," "))

# also scan err/md/build command files for /tmp and write commands, but mark as cited not necessarily tool-confirmed
cited = []
cite_re = re.compile(r"/tmp/[A-Za-z0-9._/-]+")
for folder, tag in ((LANE/".ufo/waves/round-59/w1", "w1"), (LANE/".ufo/waves/round-59/w1-abort", "abort"), (LANE/".ufo/waves/round-59/build", "build")):
    if not folder.exists():
        continue
    for p in folder.rglob("*"):
        if not p.is_file():
            continue
        if p.stat().st_size > 2_000_000:
            continue
        if p.suffix not in {".md", ".err", ".txt", ".tsv"} and p.name not in {"command.txt", "commands.md"}:
            continue
        # skip our own evidence to avoid self-echo, except we still want other seats
        if "SentinelBounds" in str(p) and tag == "build":
            continue
        try:
            text = p.read_text(errors="replace")
        except Exception:
            continue
        for m in cite_re.finditer(text):
            cited.append((tag, str(p.relative_to(LANE)), m.group(0)))

# dedupe records
seen = set()
uniq = []
for r in records:
    key = (r[0], r[1], r[2])
    if key in seen:
        continue
    seen.add(key)
    uniq.append(r)

out = EVID / "10-tool-write-paths.txt"
with out.open("w") as f:
    f.write(f"stream_files={len(streams)} raw_records={len(records)} uniq={len(uniq)}\n")
    outside = [r for r in uniq if not r[3]]
    inside_n = len(uniq) - len(outside)
    f.write(f"inside_bound={inside_n} outside_bound={len(outside)}\n")
    f.write("--- OUTSIDE ---\n")
    for seat, kind, path, ins, detail in outside:
        exists = Path(path).exists()
        f.write(f"{seat}\t{kind}\texists={exists}\t{path}\t{detail}\n")
    f.write("--- INSIDE sample count only ---\n")
    f.write(f"inside_unique={inside_n}\n")

cite_out = EVID / "11-tmp-citations.txt"
with cite_out.open("w") as f:
    seen = set()
    for tag, src, path in cited:
        key = (src, path)
        if key in seen:
            continue
        seen.add(key)
        f.write(f"{tag}\t{src}\t{path}\texists={Path(path).exists()}\n")
    f.write(f"uniq_citations={len(seen)}\n")

print(f"wrote {out} outside={sum(1 for r in uniq if not r[3])} inside={sum(1 for r in uniq if r[3])}")
print(f"tmp citations {len(set((a,b) for a,b,_ in [(x[1], x[2]) for x in cited]))}")
